        resolvedPath,
        '/deny',
        `${LOW_INTEGRITY_SID}:${flags}(F)`,
      ]);
      this.deniedCache.add(resolvedPath);
    } catch (e) {
      throw new Error(
        `Failed to deny access to forbidden path: ${resolvedPath}. ${
          e instanceof Error ? e.message : String(e)
        }`,
      );
